std::optional<fs::path> savePath(const std::string& name,bool createParents,bool directoryTarget=false){
    if(name.empty() || name.size()>1024 || name.find('\0')!=std::string::npos)return {};auto relative=fs::path(wide(name));if(relative.is_absolute() || relative.has_root_name() || relative.has_root_directory() || relative.filename().empty())return {};for(auto& part:relative){auto text=part.wstring();if(text.empty() || text.back()==L'.' || text.back()==L' ')return {};for(auto c:text)if(c<32 || c==L':' || c==L'*' || c==L'?' || c==L'"' || c==L'<' || c==L'>' || c==L'|')return {};auto base=text.substr(0,text.find(L'.'));for(auto& c:base)if(c>=L'a' && c<=L'z')c-=L'a'-L'A';if(base==L"CON" || base==L"PRN" || base==L"AUX" || base==L"NUL" || (base.size()==4 && (base.starts_with(L"COM") || base.starts_with(L"LPT")) && base[3]>=L'1' && base[3]<=L'9'))return {};}
    auto path=war3UserDirectory()/L"Saves";if(createParents)fs::create_directories(war3UserDirectory());auto directory=[&](const fs::path& dir){auto attributes=GetFileAttributesW(dir.c_str());if(attributes==INVALID_FILE_ATTRIBUTES && createParents){if(!CreateDirectoryW(dir.c_str(),nullptr) && GetLastError()!=ERROR_ALREADY_EXISTS)return false;attributes=GetFileAttributesW(dir.c_str());}return attributes!=INVALID_FILE_ATTRIBUTES && (attributes&FILE_ATTRIBUTE_DIRECTORY) && !(attributes&FILE_ATTRIBUTE_REPARSE_POINT);};if(!directory(path))return {};for(auto& part:relative.parent_path()){path/=part;if(!directory(path))return {};}path/=relative.filename();auto attributes=GetFileAttributesW(path.c_str());if(directoryTarget){if(attributes==INVALID_FILE_ATTRIBUTES || !(attributes&FILE_ATTRIBUTE_DIRECTORY) || (attributes&FILE_ATTRIBUTE_REPARSE_POINT))return {};}else if(attributes!=INVALID_FILE_ATTRIBUTES && (attributes&(FILE_ATTRIBUTE_DIRECTORY|FILE_ATTRIBUTE_REPARSE_POINT)))return {};return path;
}
struct CheckpointContents {RecoveryCheckpointInfo info;Bytes bytes;size_t offset=0,length=0;};
CheckpointContents readCheckpoint(const fs::path& dataRoot,const std::string& name){
    constexpr size_t budget=257u*1024u*1024u;validateWar3UserDirectory(dataRoot);auto path=savePath(name,false);if(!path)throw std::runtime_error("Invalid checkpoint source");auto file=CreateFileW(path->c_str(),GENERIC_READ,FILE_SHARE_READ,nullptr,OPEN_EXISTING,FILE_FLAG_OPEN_REPARSE_POINT,nullptr);if(file==INVALID_HANDLE_VALUE)throw std::runtime_error("Cannot open checkpoint: "+winError());struct Close{HANDLE file;~Close(){CloseHandle(file);}}close{file};FILE_ATTRIBUTE_TAG_INFO attributes{};LARGE_INTEGER size{};if(!GetFileInformationByHandleEx(file,FileAttributeTagInfo,&attributes,sizeof(attributes)) || (attributes.FileAttributes&(FILE_ATTRIBUTE_DIRECTORY|FILE_ATTRIBUTE_REPARSE_POINT)) || !GetFileSizeEx(file,&size) || size.QuadPart<64 || size.QuadPart>budget)throw std::runtime_error("Invalid checkpoint file");CheckpointContents result;result.bytes.resize(size_t(size.QuadPart));DWORD read=0;if(!ReadFile(file,result.bytes.data(),DWORD(result.bytes.size()),&read,nullptr) || read!=result.bytes.size())throw std::runtime_error("Cannot read checkpoint: "+winError());auto content=openSnapshot(result.bytes,budget);Binary in(content);in.expect(tag("WSAV"));if(in.u32()!=1)throw std::runtime_error("Unsupported checkpoint version");result.info.mapPath=snapshotText(in,65536);result.info.mapDigest=snapshotText(in,64);if(result.info.mapPath.empty() || result.info.mapPath.find('\0')!=std::string::npos || result.info.mapDigest.size()!=64 || !std::all_of(result.info.mapDigest.begin(),result.info.mapDigest.end(),[](unsigned char c){return (c>='0' && c<='9') || (c>='a' && c<='f');}))throw std::runtime_error("Invalid checkpoint map identity");result.length=in.u32();if(result.length>256u*1024u*1024u)throw std::runtime_error("Checkpoint bundle exceeds budget");result.offset=content.size()-in.left();auto bundle=in.take(result.length);in.finish();Binary parts(openSnapshot(bundle,256u*1024u*1024u));parts.expect(tag("SRBF"));if(!parts.u32() || snapshotText(parts,64)!=result.info.mapDigest || parts.u32()>1)throw std::runtime_error("Checkpoint map differs");auto count=parts.count(8,128);bool found=false;for(unsigned i=0;i<count;++i){auto section=snapshotText(parts,64);auto sectionSize=parts.u32();if(sectionSize>128u*1024u*1024u)throw std::runtime_error("Checkpoint component exceeds budget");auto bytes=parts.take(sectionSize);if(section!="MatchState")continue;if(found)throw std::runtime_error("Duplicate checkpoint match state");found=true;Binary match(openSnapshot(bytes,16u*1024u*1024u));match.expect(tag("SMAT"));auto format=match.u32();if((format!=1 && format!=2) || snapshotText(match,64)!=result.info.mapDigest)throw std::runtime_error("Checkpoint match context differs");snapshotU64(match);auto expansion=match.u32(),version=match.u32(),base=match.u32(),extended=match.u32(),difficulty=match.u32(),defaultDifficulty=match.u32();if(expansion>1 || version>1 || base>1 || extended>1 || difficulty>3 || defaultDifficulty>3)throw std::runtime_error("Invalid checkpoint match context");result.info.expansion=expansion!=0;result.info.version=version;result.info.defaultDifficulty=defaultDifficulty;}parts.finish();if(!found)throw std::runtime_error("Missing checkpoint match state");return result;
}
bool savedGameExists(const std::string& name){auto path=savePath(name,false);if(!path)return false;auto attributes=GetFileAttributesW(path->c_str());return attributes!=INVALID_FILE_ATTRIBUTES && !(attributes&(FILE_ATTRIBUTE_DIRECTORY|FILE_ATTRIBUTE_REPARSE_POINT));}
bool copySavedGame(const std::string& source,const std::string& destination){
    static std::atomic<unsigned> serial=0;auto from=savePath(source,false);if(!from || !savedGameExists(source))return false;auto to=savePath(destination,true);if(!to || CompareStringOrdinal(from->c_str(),-1,to->c_str(),-1,TRUE)==CSTR_EQUAL)return false;auto temporary=*to;temporary+=L"."+std::to_wstring(GetCurrentProcessId())+L"."+std::to_wstring(++serial)+L".tmp";if(!CopyFileW(from->c_str(),temporary.c_str(),TRUE))return false;if(!MoveFileExW(temporary.c_str(),to->c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH)){DeleteFileW(temporary.c_str());return false;}return true;
}
bool renameSaveDirectory(const std::string& source,const std::string& destination){
    auto from=savePath(source,false,true),to=savePath(destination,true);if(!from || !to || CompareStringOrdinal(from->c_str(),-1,to->c_str(),-1,TRUE)==CSTR_EQUAL)return false;std::map<fs::path,std::shared_ptr<void>> locks;auto hold=[&](const fs::path& path){if(locks.contains(path))return true;auto handle=CreateFileW(path.c_str(),FILE_READ_ATTRIBUTES,FILE_SHARE_READ|FILE_SHARE_WRITE,nullptr,OPEN_EXISTING,FILE_FLAG_BACKUP_SEMANTICS|FILE_FLAG_OPEN_REPARSE_POINT,nullptr);if(handle==INVALID_HANDLE_VALUE)return false;FILE_ATTRIBUTE_TAG_INFO info{};if(!GetFileInformationByHandleEx(handle,FileAttributeTagInfo,&info,sizeof(info)) || !(info.FileAttributes&FILE_ATTRIBUTE_DIRECTORY) || (info.FileAttributes&FILE_ATTRIBUTE_REPARSE_POINT)){CloseHandle(handle);return false;}locks.emplace(path,std::shared_ptr<void>(handle,[](void* value){CloseHandle(value);}));return true;};auto base=war3UserDirectory();if(!hold(base))return false;base/=L"Saves";if(!hold(base))return false;auto parents=[&](fs::path path){auto parent=base;for(auto& part:path.lexically_relative(base)){parent/=part;if(!hold(parent))return false;}return true;};if(!parents(from->parent_path()) || !parents(to->parent_path()))return false;
    auto handle=CreateFileW(from->c_str(),DELETE|FILE_READ_ATTRIBUTES,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,nullptr,OPEN_EXISTING,FILE_FLAG_BACKUP_SEMANTICS|FILE_FLAG_OPEN_REPARSE_POINT,nullptr);if(handle==INVALID_HANDLE_VALUE)return false;std::shared_ptr<void> guard(handle,[](void* value){CloseHandle(value);});FILE_ATTRIBUTE_TAG_INFO info{};if(!GetFileInformationByHandleEx(handle,FileAttributeTagInfo,&info,sizeof(info)) || !(info.FileAttributes&FILE_ATTRIBUTE_DIRECTORY) || (info.FileAttributes&FILE_ATTRIBUTE_REPARSE_POINT))return false;auto name=to->wstring();auto bytes=name.size()*sizeof(wchar_t),size=offsetof(FILE_RENAME_INFO,FileName)+bytes;std::vector<std::max_align_t> buffer((size+sizeof(std::max_align_t)-1)/sizeof(std::max_align_t));auto rename=reinterpret_cast<FILE_RENAME_INFO*>(buffer.data());rename->ReplaceIfExists=FALSE;rename->RootDirectory=nullptr;rename->FileNameLength=DWORD(bytes);std::memcpy(rename->FileName,name.data(),bytes);return SetFileInformationByHandle(handle,FileRenameInfo,rename,DWORD(size))!=0;
}
bool removeSaveDirectory(const std::string& name){
    auto root=savePath(name,false,true);if(!root)return false;std::map<fs::path,std::shared_ptr<void>> locks;auto hold=[&](const fs::path& path){auto handle=CreateFileW(path.c_str(),FILE_READ_ATTRIBUTES,FILE_SHARE_READ|FILE_SHARE_WRITE,nullptr,OPEN_EXISTING,FILE_FLAG_BACKUP_SEMANTICS|FILE_FLAG_OPEN_REPARSE_POINT,nullptr);if(handle==INVALID_HANDLE_VALUE)return false;FILE_ATTRIBUTE_TAG_INFO info{};if(!GetFileInformationByHandleEx(handle,FileAttributeTagInfo,&info,sizeof(info)) || !(info.FileAttributes&FILE_ATTRIBUTE_DIRECTORY) || (info.FileAttributes&FILE_ATTRIBUTE_REPARSE_POINT)){CloseHandle(handle);return false;}locks.emplace(path,std::shared_ptr<void>(handle,[](void* value){CloseHandle(value);}));return true;};auto path=war3UserDirectory();if(!hold(path))return false;path/=L"Saves";if(!hold(path))return false;for(auto& part:root->lexically_relative(path)){path/=part;if(!hold(path))return false;}
    std::vector<fs::path> entries;std::error_code error;fs::recursive_directory_iterator it(*root,fs::directory_options::none,error),end;if(error)return false;for(;it!=end;it.increment(error)){if(error || it.depth()>64 || entries.size()>=65536)return false;auto attributes=GetFileAttributesW(it->path().c_str());if(attributes==INVALID_FILE_ATTRIBUTES || (attributes&FILE_ATTRIBUTE_REPARSE_POINT) || ((attributes&FILE_ATTRIBUTE_DIRECTORY) && !hold(it->path())))return false;entries.push_back(it->path());}if(error)return false;for(auto entry=entries.rbegin();entry!=entries.rend();++entry){locks.erase(*entry);if(!fs::remove(*entry,error) || error)return false;}locks.erase(*root);return fs::remove(*root,error) && !error;
}
