void ScriptSession::saveRecoveryCheckpoint(const std::string& name,bool overwrite) const {
    constexpr size_t budget=257u*1024u*1024u;if(!world_)throw std::runtime_error("Checkpoint requires a mounted map");validateWar3UserDirectory(world_->resources().root());auto path=savePath(name,true);if(!path)throw std::runtime_error("Invalid checkpoint destination");auto bundle=encodeRecoveryBundle();SnapshotWriter out(budget-64);out.u32(tag("WSAV"));out.u32(1);out.text(utf8(world_->resources().mapPath().wstring()),65536);out.text(world_->resources().mapDigest(),64);out.size(bundle.size());out.raw(bundle);auto bytes=sealSnapshot(out.finish(),budget);static std::atomic<unsigned> serial=0;auto temporary=*path;temporary+=L"."+std::to_wstring(GetCurrentProcessId())+L"."+std::to_wstring(++serial)+L".tmp";auto file=CreateFileW(temporary.c_str(),GENERIC_WRITE,0,nullptr,CREATE_NEW,FILE_ATTRIBUTE_NORMAL,nullptr);if(file==INVALID_HANDLE_VALUE)throw std::runtime_error("Cannot create checkpoint temporary file: "+winError());DWORD written=0;bool ok=WriteFile(file,bytes.data(),DWORD(bytes.size()),&written,nullptr) && written==bytes.size() && FlushFileBuffers(file);auto error=ok?ERROR_SUCCESS:GetLastError();CloseHandle(file);if(!ok){DeleteFileW(temporary.c_str());throw std::runtime_error("Cannot write checkpoint: "+winError(error));}if(!MoveFileExW(temporary.c_str(),path->c_str(),(overwrite?MOVEFILE_REPLACE_EXISTING:0)|MOVEFILE_WRITE_THROUGH)){error=GetLastError();DeleteFileW(temporary.c_str());throw std::runtime_error("Cannot publish checkpoint: "+winError(error));}
}
void ScriptSession::saveLocalGame(const std::string& name,bool overwrite) {
    if(!mainAttempted_ || !mainCompleted_ || failed_ || unitRecoveryIncomplete_ || experimentalSelectionSync_ || !networkPlayers_.empty() || pendingSave_ || localSaveInProgress_ || exitRequest()!=SessionExit::None || !runtime_.snapshotSafe() || !contexts_.empty())throw std::runtime_error("Local save requires an active local session at a safe boundary");
    localSaveInProgress_=true;struct Reset{bool& active;~Reset(){active=false;}}reset{localSaveInProgress_};saveRecoveryCheckpoint(name,overwrite);notifyGameSaved(name);
}
RecoveryCheckpointInfo ScriptSession::inspectRecoveryCheckpoint(const fs::path& dataRoot,const std::string& name) {return readCheckpoint(dataRoot,name).info;}
fs::path ScriptSession::resolveRecoveryCheckpointMap(const fs::path& dataRoot,const std::string& name,const fs::path& externalRoot) {
    auto info=inspectRecoveryCheckpoint(dataRoot,name);auto maps=fs::canonical(dataRoot/L"Maps");auto external=externalRoot.empty()?fs::path{}:fs::canonical(externalRoot);if(!external.empty() && !fs::is_directory(external))throw std::runtime_error("Invalid checkpoint external map root");auto within=[](const fs::path& root,const fs::path& path){if(root.empty())return false;auto prefix=root.wstring(),candidate=path.wstring();if(!prefix.empty() && prefix.back()!=L'\\')prefix+=L'\\';return candidate.size()>=prefix.size() && CompareStringOrdinal(prefix.c_str(),int(prefix.size()),candidate.c_str(),int(prefix.size()),TRUE)==CSTR_EQUAL;};auto hint=fs::path(wide(info.mapPath));std::vector<fs::path> candidates;if(hint.is_absolute())candidates.push_back(hint);else if(!hint.has_root_name() && !hint.has_root_directory()){if(!external.empty())candidates.push_back(external/hint);candidates.push_back(dataRoot/hint);candidates.push_back(maps/hint);candidates.push_back(maps/L"FrozenThrone"/L"Campaign"/hint);candidates.push_back(maps/L"Campaign"/hint);}for(auto& candidate:candidates){std::error_code error;auto path=fs::canonical(candidate,error);if(error || (!within(maps,path) && !within(external,path)) || !fs::is_regular_file(path,error) || error)continue;auto extension=path.extension().wstring();std::transform(extension.begin(),extension.end(),extension.begin(),[](wchar_t c){return wchar_t(std::towlower(c));});if(extension!=L".w3m" && extension!=L".w3x")continue;if(sha256(path)==info.mapDigest)return path;}throw std::runtime_error("Cannot locate checkpoint map with matching identity");
}
std::map<std::uint32_t,std::uint32_t> ScriptSession::restoreRecoveryCheckpoint(const std::string& name) {
    if(!world_)throw std::runtime_error("Checkpoint requires a mounted map");auto data=readCheckpoint(world_->resources().root(),name);if(data.info.mapDigest!=world_->resources().mapDigest())throw std::runtime_error("Checkpoint map differs");return restoreRecoveryBundle(std::span<const std::uint8_t>(data.bytes).subspan(data.offset,data.length));
}
void ScriptSession::processPendingSave() {
    if(!pendingSave_)return;auto request=*pendingSave_;saveRecoveryCheckpoint(request.name);notifyGameSaved(request.name);if(!runtime_.wakeExternal(request.token))throw std::runtime_error("Saved game caller is no longer waiting");pendingSave_.reset();
}
void ScriptSession::notifyGameLoaded(){
    if(!recoveryBundleRestored_ || !unitRecoveryIncomplete_ || mainAttempted_ || gameLoadNotified_ || failed_ || !runtime_.snapshotSafe() || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty())throw std::runtime_error("Game load notification requires a recovered local session");struct Guard{bool& failed;bool done=false;~Guard(){if(!done)failed=true;}}guard{failed_};gameLoadNotified_=true;config_.mapFlags|=8192u*64u;std::vector<std::uint32_t> pending;for(auto id:eventHandles_)if(alive(id,NativeKind::Event)){auto& event=std::get<ScriptEvent>(objects_[id-handleBase].state);if(event.kind==ScriptEvent::Kind::Game && event.event==256)pending.push_back(id);}for(auto id:pending)fire(id);guard.done=true;
}
void ScriptSession::notifyGameSaved(const std::string& filename){
    if(filename.empty() || filename.size()>1024 || filename.find('\0')!=std::string::npos)throw std::runtime_error("Invalid saved game event filename");std::vector<std::uint32_t> pending;for(auto id:eventHandles_)if(alive(id,NativeKind::Event)){auto& event=std::get<ScriptEvent>(objects_[id-handleBase].state);if(event.kind==ScriptEvent::Kind::Game && event.event==259)pending.push_back(id);}ScriptContext context;context.saveName=filename;for(auto id:pending)fire(id,context);
}
void ScriptSession::bindCampaignNatives(){
    auto integer=[](jass::Value value){return std::bit_cast<std::int32_t>(value.bits);};auto protect=[this]{if(world_)validateWar3UserDirectory(world_->resources().root());};
    bind("SetCampaignAvailable","nothing",{"integer","boolean"},[this,integer,protect](auto& vm,auto a){protect();auto index=integer(a[0]);if(index<0)throw std::runtime_error("Negative campaign index");CampaignProfile profile;profile.setCampaign(campaignExpansion_,unsigned(index),a[1].bits!=0);return vm.nothing();});
    bind("SetMissionAvailable","nothing",{"integer","integer","boolean"},[this,integer,protect](auto& vm,auto a){protect();auto campaign=integer(a[0]),mission=integer(a[1]);if(campaign<0 || mission<0)throw std::runtime_error("Negative campaign mission index");CampaignProfile profile;profile.setMission(campaignExpansion_,unsigned(campaign),unsigned(mission),a[2].bits!=0);return vm.nothing();});
    for(auto [name,ending]:std::initializer_list<std::pair<const char*,bool>>{{"SetOpCinematicAvailable",false},{"SetEdCinematicAvailable",true}})bind(name,"nothing",{"integer","boolean"},[this,integer,ending,protect](auto& vm,auto a){protect();auto index=integer(a[0]);if(index<0)throw std::runtime_error("Negative cinematic campaign index");CampaignProfile profile;profile.setCinematic(campaignExpansion_,unsigned(index),ending,a[1].bits!=0);return vm.nothing();});
    bind("SetTutorialCleared","nothing",{"boolean"},[protect](auto& vm,auto a){protect();CampaignProfile profile;profile.setTutorial(a[0].bits!=0);return vm.nothing();});
    bind("SetCampaignMenuRace","nothing",{"race"},[protect](auto& vm,auto a){protect();unsigned index=a[0].bits==7?0:a[0].bits==1?1:a[0].bits==3?2:a[0].bits==2?3:a[0].bits==4?4:UINT_MAX;if(index!=UINT_MAX){CampaignProfile profile;profile.select(false,index);}return vm.nothing();});
    bind("SetCampaignMenuRaceEx","nothing",{"integer"},[integer,protect](auto& vm,auto a){protect();auto index=integer(a[0]);if(index>=0 && index<4){CampaignProfile profile;profile.select(true,unsigned(index));}return vm.nothing();});
    bind("ForceCampaignSelectScreen","nothing",{},[this](auto& vm,auto){forceCampaignSelect_=true;return vm.nothing();});
    bind("GetSaveBasicFilename","string",{},[this](auto& vm,auto){if(contexts_.empty() || contexts_.back().event!=259 || contexts_.back().saveName.empty())return jass::Value{vm.module().typeId("string"),0,{}};auto& filename=contexts_.back().saveName;auto separator=filename.find_last_of("/\\");auto name=filename.substr(separator==std::string::npos?0:separator+1,259);auto dot=name.find_last_of('.');if(dot!=std::string::npos)name.resize(dot);return vm.string(std::move(name));});
    bind("SaveGame","nothing",{"string"},[this,protect](auto& vm,auto a){if(&vm!=&runtime_ || !vm.currentThread() || !mainAttempted_ || unitRecoveryIncomplete_ || experimentalSelectionSync_ || !networkPlayers_.empty() || pendingSave_ || localSaveInProgress_)throw std::runtime_error("SaveGame requires an available local script checkpoint");if(!a[0].text || a[0].text->empty() || a[0].text->size()>1024 || a[0].text->find('\0')!=std::string::npos)throw std::runtime_error("Invalid saved game filename");protect();auto name=*a[0].text;auto token=vm.prepareExternalWait();try{pendingSave_.emplace(PendingSave{std::move(name),token});}catch(...){vm.cancelExternalWait(token);throw;}vm.waitExternal(token);return vm.nothing();});
    if(runtime_.module().functionId("SaveGame")!=jass::none)runtime_.markNativeCompletedOnResume("SaveGame");
    bind("SaveGameExists","boolean",{"string"},[protect](auto& vm,auto a){protect();try{return vm.boolean(a[0].text && savedGameExists(*a[0].text));}catch(const std::exception&){return vm.boolean(false);}});
    bind("CopySaveGame","boolean",{"string","string"},[protect](auto& vm,auto a){protect();try{return vm.boolean(a[0].text && a[1].text && copySavedGame(*a[0].text,*a[1].text));}catch(const std::exception&){return vm.boolean(false);}});
    bind("RenameSaveDirectory","boolean",{"string","string"},[protect](auto& vm,auto a){protect();try{return vm.boolean(a[0].text && a[1].text && renameSaveDirectory(*a[0].text,*a[1].text));}catch(const std::exception&){return vm.boolean(false);}});
    bind("RemoveSaveDirectory","boolean",{"string"},[protect](auto& vm,auto a){protect();try{return vm.boolean(a[0].text && removeSaveDirectory(*a[0].text));}catch(const std::exception&){return vm.boolean(false);}});
    for(auto [name,model]:std::initializer_list<std::pair<const char*,bool>>{{"PlayCinematic",false},{"PlayModelCinematic",true}})bind(name,"nothing",{"string"},[this,model](auto& vm,auto a){auto value=a[0].text?*a[0].text:std::string{};if(value.size()>1024 || value.find('\0')!=std::string::npos)throw std::runtime_error("Invalid cinematic request");(model?modelCinematic_:movieCinematic_)=std::move(value);return vm.nothing();});
    bind("LoadGame","nothing",{"string","boolean"},[this](auto& vm,auto a){if(!world_ || !a[0].text || a[0].text->empty() || a[0].text->size()>1024 || a[0].text->find('\0')!=std::string::npos)throw std::runtime_error("Invalid load game filename");if(&vm!=&runtime_ || !vm.currentThread() || unitRecoveryIncomplete_ || experimentalSelectionSync_ || !networkPlayers_.empty() || pendingSave_ || localSaveInProgress_)throw std::runtime_error("LoadGame requires a local active script thread");auto map=world_->resources().mapPath();auto external=map.is_absolute()?map.parent_path():fs::path{};auto resolved=resolveRecoveryCheckpointMap(world_->resources().root(),*a[0].text,external);auto token=vm.prepareExternalWait();try{nextCheckpoint_=*a[0].text;nextLevel_=utf8(resolved.wstring());finishGame(a[1].bits!=0,SessionExit::ChangeLevel);vm.waitExternal(token);}catch(...){vm.cancelExternalWait(token);throw;}return vm.nothing();});
    bind("ChangeLevel","nothing",{"string","boolean"},[this](auto& vm,auto a){if(!a[0].text || a[0].text->empty() || a[0].text->size()>1024)throw std::runtime_error("Invalid next-level path");if(experimentalSelectionSync_)throw std::runtime_error("ChangeLevel is not yet supported in experimental LAN or replay sessions");nextCheckpoint_.clear();nextLevel_=*a[0].text;finishGame(a[1].bits!=0,SessionExit::ChangeLevel);return vm.nothing();});
}
